//! 🎟️ The actual Host root keeps one paid source and exact suspended turn through guest receipt acknowledgement.
#[path="../🦀️.rs"]
mod original;
use original::*;
use semio_framework_actor::{RetainedTurnInput,OriginalJobTurnLoan};
use semio_framework_job::OriginalTurnFailure;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
use std::sync::atomic::{AtomicU64,Ordering};
static NOW:AtomicU64=AtomicU64::new(1000);
fn clock()->Option<u64>{Some(NOW.load(Ordering::Acquire))}
#[global_allocator]
static ALLOCATOR:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
/// 📬️ Real root controls and the actual guest turn loan preserve their source, clock, recipient and physical currencies.
#[test]
fn original_host_root_pending_receipt_keeps_source_scope_after_expiry_and_cancellation(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let policy:GuestRelayRootPolicy=serde_json::from_value(law["policy"].clone()).unwrap();NOW.store(law["clock"].as_u64().unwrap(),Ordering::Release);
 let grant=RetainedCloneGrant{maximum_items:8,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let mut root=GuestRelayOriginalRoot::new(policy,clock).unwrap();let mut epoch=0;let mut born=0;loop{epoch+=1;let input=RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant};let((ready,spent,_),heap)=observe(||root.admit_step(input).unwrap());assert_eq!((spent.retained_capacity_bytes,spent.released_bytes),heap);born+=heap.0;if ready{break}assert!(epoch<16)}assert!(born>0);
 epoch+=1;let input=RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant};let budget=root.issued_budget(input).unwrap();assert_eq!(budget.deadline_us,law["deadline"].as_u64().unwrap());root.begin_turn(7,13,input,budget).unwrap();let mut loan=OriginalJobTurnLoan::new();let mut recipient=0;
 let pending=root.dispatch_step(7,13,false,|cx|{recipient=cx.original_recipient_identity();assert_eq!((cx.operation().0,cx.generation().0),(policy.operation,policy.generation));cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:23,..Default::default()})?;cx.consume_fuel(1);Ok::<_,OriginalTurnFailure>(loan.checkout(input,cx)?.unwrap())}).unwrap();assert_eq!(pending.fuel,law["scope"]["fuel"].as_u64().unwrap());root.hold_pending(7,13,pending).unwrap();let execution=root.checkout_execution_budget(7,13,pending).unwrap();assert_ne!(execution.fuel,pending.fuel);assert_eq!(execution.fuel,policy.turn_execution_fuel);
 for forged in [semio_framework_actor::OriginalJobBudget{deadline_us:pending.deadline_us+1,..pending},semio_framework_actor::OriginalJobBudget{fuel:pending.fuel+1,..pending},semio_framework_actor::OriginalJobBudget{input:RetainedTurnInput{epoch:pending.input.epoch+1,..pending.input},..pending},semio_framework_actor::OriginalJobBudget{input:RetainedTurnInput{grant,..pending.input},..pending}]{let(result,heap)=observe(||root.dispatch_pending_step(7,13,forged,false,|_|Ok(())));assert!(result.is_err());assert_eq!(heap,(0,0));}
 assert!(root.finish_turn(7,13).is_err());assert!(root.issued_budget(RetainedTurnInput{epoch:epoch+1,..input}).is_err());assert!(root.pending_budget(8,13).is_err());assert!(root.pending_budget(7,14).is_err());NOW.store(budget.deadline_us+1,Ordering::Release);
 let(_,heap)=observe(||root.dispatch_pending_step(7,13,pending,true,|cx|{assert_eq!(cx.original_recipient_identity(),recipient);assert_eq!(cx.deadline_us(),pending.deadline_us);assert!(cx.is_cancelled());assert!(cx.deadline_exceeded());loan.receive(pending.input,RetainedCloneProgress{copied_items:1,copied_bytes:41,..Default::default()},5,cx)?;Ok(())}).unwrap());assert_eq!(heap,(0,0));assert!(loan.terminal_is_empty());root.acknowledge_pending(7,13,pending).unwrap();let returned=root.pending_budget(7,13).unwrap();assert_eq!(returned.fuel,law["expected"]["fuel"].as_u64().unwrap());assert_eq!(returned.input.grant.maximum_copy_bytes,law["expected"]["grant"][1].as_u64().unwrap()as usize);assert!(root.finish_turn(7,13).is_err());assert!(root.receive_execution_receipt(7,13,semio_framework_actor::OriginalGuestExecutionReceipt{budget:execution,spent_fuel:None,submitted:true}).is_err());assert!(root.receive_execution_receipt(7,13,semio_framework_actor::OriginalGuestExecutionReceipt{budget:execution,spent_fuel:Some(execution.fuel+1),submitted:true}).is_err());root.receive_execution_receipt(7,13,semio_framework_actor::OriginalGuestExecutionReceipt{budget:execution,spent_fuel:Some(73),submitted:true}).unwrap();let(receipt,work,execution_work)=root.finish_turn(7,13).unwrap();assert_eq!(execution_work,73);assert_eq!(root.execution_fuel_remaining(),policy.operation_execution_fuel-73);assert_eq!(work,6);assert_eq!(receipt.spent,RetainedCloneProgress{copied_items:2,copied_bytes:64,..Default::default()});
 let mut released=0;for _ in 0..32{if root.terminal_is_empty(){break}epoch+=1;let(step,heap)=observe(||root.close_step(RetainedTurnInput{epoch,..input}).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);released+=heap.1;}assert!(root.terminal_is_empty());assert_eq!(released,born);assert_eq!(observe(||drop(root)).1,(0,0));assert_eq!(observe(||drop(loan)).1,(0,0));eprintln!("[DEBUG] actual original Host source paidBirth={born} paidRelease={released} exactPendingEpoch={epoch} logicalWork6 independentExecution73 receiptCopy64 afterExpiryAndCancellation=true noNewDeadline=true sameRecipient={recipient}");
}

/// 📤️ A real guest context reaches Ready before its original instance input can be paid into its final owner.
#[test]
fn original_host_root_ready_input_transfer_preserves_denied_final_owner(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let policy:GuestRelayRootPolicy=serde_json::from_value(law["policy"].clone()).unwrap();NOW.store(1000,Ordering::Release);let grant=RetainedCloneGrant{maximum_items:16,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let mut root=GuestRelayOriginalRoot::new(policy,clock).unwrap();let mut epoch=0;let mut born=0;
 loop{epoch+=1;let((ready,spent,_),heap)=observe(||root.admit_step(RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant}).unwrap());assert_eq!((spent.retained_capacity_bytes,spent.released_bytes),heap);born+=heap.0;if ready{break}assert!(epoch<16)}
 let mut guest=semio_framework_actor::retained_turn::context::OriginalActorContextSlot::empty();let mut owner:Option<semio_framework_actor::retained_turn::OriginalActorInput<[u8;41]>>=None;let mut previous:Option<semio_framework_actor::RetainedTurnReceipt>=None;
 loop{epoch+=1;let input=RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant:previous.map_or(grant,|receipt|receipt.remaining)};let budget=root.issued_budget(input).unwrap();root.begin_actor_scope(input,budget).unwrap();let((ready,spent),heap)=observe(||root.dispatch_actor_step(input,false,|cx|{
  if owner.is_none(){cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:41,..Default::default()})?;cx.consume_fuel(1);let budget=semio_framework_actor::OriginalJobBudget::borrow_original(input,cx)?;owner=Some(semio_framework_actor::retained_turn::OriginalActorInput::new([83;41],budget.input).unwrap());}else{owner.as_mut().unwrap().receive_next_issued(input)?;}
  let owner=owner.as_mut().unwrap();let issued=*owner.issued_input().unwrap();let issued=owner.checkout_guest(issued.grant)?.unwrap();let call=guest.admit_step(issued);let admission=call.result?;owner.receive_guest_spent(call.input,call.receipt_spent,if admission.ready{semio_framework_actor::retained_turn::ActorGuestPhase::Ready}else{owner.phase()})?;let receipt=owner.return_actor_turn()?;cx.consume_retained(call.receipt_spent)?;previous=Some(receipt);Ok((admission.ready,call.receipt_spent))
 }).unwrap());assert_eq!((spent.retained_capacity_bytes,spent.released_bytes),heap);born+=heap.0;root.finish_actor_scope(input).unwrap();if ready{break}assert!(epoch<32)}
 let mut owner=owner.unwrap();let pointer=owner.original().unwrap().as_ptr();for copy in [40,41]{epoch+=1;let input=RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant:RetainedCloneGrant{maximum_copy_bytes:copy,..grant}};let budget=root.issued_budget(input).unwrap();root.begin_actor_scope(input,budget).unwrap();let(taken,heap)=observe(||root.dispatch_actor_step(input,false,|cx|owner.take_admitted_input_step(cx)).unwrap());assert_eq!(heap,(0,0));let(receipt,work,_)=root.finish_actor_scope(input).unwrap();if copy==40{assert!(taken.is_none());assert_eq!(owner.original().unwrap().as_ptr(),pointer);assert_eq!(receipt.spent,Default::default());assert_eq!(work,0)}else{assert_eq!(taken.unwrap(),[83;41]);assert!(owner.original().is_none());assert_eq!(receipt.spent,RetainedCloneProgress{copied_items:1,copied_bytes:41,..Default::default()});assert_eq!(work,1)}}assert_eq!(observe(||drop(owner)).1,(0,0));
 let mut released=0;for _ in 0..32{if guest.terminal_is_empty(){break}epoch+=1;let input=RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant};let budget=root.issued_budget(input).unwrap();root.begin_actor_scope(input,budget).unwrap();let(step,heap)=observe(||root.dispatch_actor_step(input,false,|cx|{let call=guest.close_step(input);let step=call.result.unwrap();cx.consume_retained(call.receipt_spent)?;Ok(step)}).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);released+=heap.1;root.finish_actor_scope(input).unwrap();}assert!(guest.terminal_is_empty());assert_eq!(observe(||drop(guest)).1,(0,0));for _ in 0..32{if root.terminal_is_empty(){break}epoch+=1;let(step,heap)=observe(||root.close_step(RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant}).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);released+=heap.1;}assert!(root.terminal_is_empty());assert_eq!(released,born);assert_eq!(observe(||drop(root)).1,(0,0));eprintln!("[DEBUG] actual original Actor ready transfer source71/3 paid41 denied40 sameOwner=true noFakeDispatched=true guestPaidContext=true born={born} released={released}");
}

/// ⏳️ An expired authentic callback retains its startup machine; the real root alone issues the following deadline slice.
#[test]
fn original_host_root_startup_expiry_keeps_machine_until_next_authenticated_root_slice(){
 use semio_framework_plugin_interpreter::interpreter::{CoreModule,CoreInstanceOpening,CoreOriginalInvocationStatus,Value};
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let policy:GuestRelayRootPolicy=serde_json::from_value(law["policy"].clone()).unwrap();NOW.store(1000,Ordering::Release);let grant=RetainedCloneGrant{maximum_items:16,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let bytes=[0,97,115,109,1,0,0,0,1,5,1,96,0,1,126,3,2,1,0,10,6,1,4,0,66,1,11];let module=std::sync::Arc::new(CoreModule::parse(&bytes).unwrap());let mut root=GuestRelayOriginalRoot::new(policy,clock).unwrap();let mut epoch=0;let mut born=0;loop{epoch+=1;let((ready,spent,_),heap)=observe(||root.admit_step(RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant}).unwrap());assert_eq!((spent.retained_capacity_bytes,spent.released_bytes),heap);born+=heap.0;if ready{break}assert!(epoch<16)}
 let mut owner=None;for _ in 0..32{epoch+=1;let input=RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant};let budget=root.issued_budget(input).unwrap();root.begin_actor_scope(input,budget).unwrap();let(ready,heap)=observe(||root.dispatch_actor_step(input,false,|cx|{if owner.is_none(){owner=CoreInstanceOpening::begin(&module,cx)?;Ok(false)}else{owner.as_mut().unwrap().advance(&module,cx)}}).unwrap());let(receipt,_,_)=root.finish_actor_scope(input).unwrap();assert_eq!((receipt.spent.retained_capacity_bytes,receipt.spent.released_bytes),heap);born+=heap.0;if ready{break}}let mut owner=owner.unwrap();assert!(owner.resources_ready());epoch+=1;let input=RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant};let budget=root.issued_budget(input).unwrap();root.begin_actor_scope(input,budget).unwrap();let(ready,heap)=observe(||root.dispatch_actor_step(input,false,|cx|owner.begin_function_step(&module,0,&[],cx)).unwrap());assert!(ready);let(receipt,_,_)=root.finish_actor_scope(input).unwrap();assert_eq!((receipt.spent.retained_capacity_bytes,receipt.spent.released_bytes),heap);born+=heap.0;
 epoch+=1;let input=RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant};let budget=root.issued_budget(input).unwrap();root.begin_actor_scope(input,budget).unwrap();let execution=root.checkout_actor_execution_budget(input).unwrap();NOW.store(budget.deadline_us+1,Ordering::Release);let(call,heap)=observe(||root.dispatch_actor_step(input,false,|cx|owner.advance_scalar(&module,execution,cx)).unwrap());assert_eq!(heap,(0,0));assert_eq!(call.result.unwrap(),CoreOriginalInvocationStatus::Deadline);assert_eq!(call.execution.spent_fuel,Some(0));assert!(owner.invocation_values().is_none());root.receive_actor_execution_receipt(input,call.execution).unwrap();let(receipt,work,vm)=root.finish_actor_scope(input).unwrap();assert_eq!(receipt.spent,Default::default());assert_eq!((work,vm),(0,0));
 epoch+=1;let input=RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant};let next=root.issued_budget(input).unwrap();assert!(next.deadline_us>budget.deadline_us);root.begin_actor_scope(input,next).unwrap();let execution=root.checkout_actor_execution_budget(input).unwrap();let(call,heap)=observe(||root.dispatch_actor_step(input,false,|cx|owner.advance_scalar(&module,execution,cx)).unwrap());assert_eq!(call.result.unwrap(),CoreOriginalInvocationStatus::Complete);assert_eq!(call.execution.spent_fuel,Some(2));root.receive_actor_execution_receipt(input,call.execution).unwrap();let(receipt,work,vm)=root.finish_actor_scope(input).unwrap();assert_eq!((receipt.spent.retained_capacity_bytes,receipt.spent.released_bytes),heap);assert_eq!(vm,2);assert!(work>vm);born+=heap.0;assert_eq!(owner.invocation_values().unwrap(),&[Value::I64(1)]);
 let mut released=0;for _ in 0..80{if owner.terminal_is_empty(){break}epoch+=1;let input=RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant};let budget=root.issued_budget(input).unwrap();root.begin_actor_scope(input,budget).unwrap();let(_,heap)=observe(||root.dispatch_actor_step(input,true,|cx|owner.close_step(&module,cx)).unwrap());let(receipt,_,_)=root.finish_actor_scope(input).unwrap();assert_eq!((receipt.spent.retained_capacity_bytes,receipt.spent.released_bytes),heap);released+=heap.1;}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));for _ in 0..32{if root.terminal_is_empty(){break}epoch+=1;let(step,heap)=observe(||root.close_step(RetainedTurnInput{operation:policy.operation,generation:policy.generation,epoch,grant}).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);released+=heap.1;}assert!(root.terminal_is_empty());assert_eq!(born,released);assert_eq!(observe(||drop(root)).1,(0,0));eprintln!("[DEBUG] actual original Root startup expiredSliceMeasured0=true originalMachineRetained=true laterRootIssuerDeadline={} initiatingDeadline={} laterMeasuredVM2=true logicalWorkIndependent=true physicalBirth={born} paidRelease={released}",next.deadline_us,budget.deadline_us);
}
